package vn.covie.inventory.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import com.fasterxml.jackson.databind.JsonNode; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="inventory_movements") public class InventoryMovementEntity { @Id private UUID id; @Column(name="location_variant_id",nullable=false) private UUID locationVariantId; @Enumerated(EnumType.STRING) @Column(name="movement_type",nullable=false) private InventoryMovementType movementType; @Column(nullable=false) private long quantity; @Column(name="order_id") private UUID orderId; @Column(name="order_item_id") private UUID orderItemId; @Column(name="reservation_id") private UUID reservationId; @Column(name="actor_user_id") private UUID actorUserId; @Column(name="reason_code") private String reasonCode; @JdbcTypeCode(SqlTypes.JSON) @Column(columnDefinition="jsonb") private JsonNode metadata; @Column(name="created_at",nullable=false) private Instant createdAt; protected InventoryMovementEntity(){} public static InventoryMovementEntity create(UUID id,UUID variant,InventoryMovementType type,long quantity,UUID order,UUID item,UUID reservation,UUID actor,String reason,JsonNode meta,Instant now){InventoryMovementEntity m=new InventoryMovementEntity();m.id=id;m.locationVariantId=variant;m.movementType=type;m.quantity=quantity;m.orderId=order;m.orderItemId=item;m.reservationId=reservation;m.actorUserId=actor;m.reasonCode=reason;m.metadata=meta;m.createdAt=now;return m;} public UUID getId(){return id;} public long getQuantity(){return quantity;} public InventoryMovementType getMovementType(){return movementType;} }
